insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('af392dbb-e70e-43e4-a3e2-95a08311a25a', '4e6074d2-8d41-4d91-afdd-1605a7516843', null, 'topic'::public.curated_course_node_type, 'Data and variation', 'This module establishes data and variation as the course''s first working framework. It supplies the language and representations needed before the path advances to probability foundations.', 0),
  ('db315517-3094-41dc-a896-2ac651000d87', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'af392dbb-e70e-43e4-a3e2-95a08311a25a', 'subtopic'::public.curated_course_node_type, 'Populations', 'Populations identifies a specific object, distinction, or relationship within data and variation. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before samples because that next topic assumes this starting point.', 0),
  ('af57acd1-68fd-4820-bbd8-5ec4ca45dfc8', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'af392dbb-e70e-43e4-a3e2-95a08311a25a', 'subtopic'::public.curated_course_node_type, 'Samples', 'Samples identifies a specific object, distinction, or relationship within data and variation. Learners need to recognize and use it before combining this module''s ideas in later work. After populations, samples supplies what is needed to address measurement scales.', 1),
  ('86f44056-acec-4700-a566-99e3a60b3218', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'af392dbb-e70e-43e4-a3e2-95a08311a25a', 'subtopic'::public.curated_course_node_type, 'Measurement scales', 'Measurement scales connects data and variation to observable evidence and defines what a valid measurement or interpretation must support. After samples, measurement scales supplies what is needed to address visualization.', 2),
  ('600436fb-1030-4c8d-86b0-2d2835be89b1', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'af392dbb-e70e-43e4-a3e2-95a08311a25a', 'subtopic'::public.curated_course_node_type, 'Visualization', 'Visualization connects data and variation to observable evidence and defines what a valid measurement or interpretation must support. After measurement scales, visualization supplies what is needed to address robust summaries.', 3),
  ('b3e2eca1-a85e-46ec-9e91-9fbd084deac0', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'af392dbb-e70e-43e4-a3e2-95a08311a25a', 'subtopic'::public.curated_course_node_type, 'Robust summaries', 'Robust summaries identifies a specific object, distinction, or relationship within data and variation. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, robust summaries carries the completed idea into probability foundations.', 4),
  ('fd63b73b-0d4d-4101-b190-0de659774b44', '4e6074d2-8d41-4d91-afdd-1605a7516843', null, 'topic'::public.curated_course_node_type, 'Probability foundations', 'This module builds directly on data and variation and develops probability foundations. It belongs here because its methods and distinctions are prerequisites for discrete models.', 1),
  ('0609bfd6-ee0e-423b-81cb-2fd7af8f94a7', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'fd63b73b-0d4d-4101-b190-0de659774b44', 'subtopic'::public.curated_course_node_type, 'Rules', 'Rules identifies a specific object, distinction, or relationship within probability foundations. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before counting because that next topic assumes this starting point.', 0),
  ('fbc49065-7eb9-42f4-adf9-d99d8542b854', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'fd63b73b-0d4d-4101-b190-0de659774b44', 'subtopic'::public.curated_course_node_type, 'Counting', 'Counting identifies a specific object, distinction, or relationship within probability foundations. Learners need to recognize and use it before combining this module''s ideas in later work. After rules, counting supplies what is needed to address conditioning.', 1),
  ('6b028c0a-c285-482d-9ff6-4b9ee994831d', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'fd63b73b-0d4d-4101-b190-0de659774b44', 'subtopic'::public.curated_course_node_type, 'Conditioning', 'Conditioning identifies a specific object, distinction, or relationship within probability foundations. Learners need to recognize and use it before combining this module''s ideas in later work. After counting, conditioning supplies what is needed to address independence.', 2),
  ('17bdcf93-7534-4434-8851-b4917a7348a5', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'fd63b73b-0d4d-4101-b190-0de659774b44', 'subtopic'::public.curated_course_node_type, 'Independence', 'Independence identifies a specific object, distinction, or relationship within probability foundations. Learners need to recognize and use it before combining this module''s ideas in later work. After conditioning, independence supplies what is needed to address bayes’ theorem.', 3),
  ('052c368c-554a-4e59-9205-326891d1d149', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'fd63b73b-0d4d-4101-b190-0de659774b44', 'subtopic'::public.curated_course_node_type, 'Bayes’ theorem', 'Bayes’ theorem provides a formal guarantee or inference rule for probability foundations, allowing later conclusions to be justified rather than inferred from examples alone. As the final topic in this module, bayes’ theorem carries the completed idea into discrete models.', 4),
  ('8049817a-9d6a-4979-9b3a-e3f3ae7d9b19', '4e6074d2-8d41-4d91-afdd-1605a7516843', null, 'topic'::public.curated_course_node_type, 'Discrete models', 'This module builds directly on probability foundations and develops discrete models. It belongs here because its methods and distinctions are prerequisites for continuous models.', 2),
  ('334fcfaf-b11a-4ae8-99eb-16f64cce836a', '4e6074d2-8d41-4d91-afdd-1605a7516843', '8049817a-9d6a-4979-9b3a-e3f3ae7d9b19', 'subtopic'::public.curated_course_node_type, 'Binomial', 'Binomial identifies a specific object, distinction, or relationship within discrete models. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before geometric because that next topic assumes this starting point.', 0),
  ('44072535-f3e2-4612-87eb-40a03f5e9ebc', '4e6074d2-8d41-4d91-afdd-1605a7516843', '8049817a-9d6a-4979-9b3a-e3f3ae7d9b19', 'subtopic'::public.curated_course_node_type, 'Geometric', 'Geometric identifies a specific object, distinction, or relationship within discrete models. Learners need to recognize and use it before combining this module''s ideas in later work. After binomial, geometric supplies what is needed to address hypergeometric.', 1),
  ('6861edb8-636a-4d8c-a518-67d3b9bcbb22', '4e6074d2-8d41-4d91-afdd-1605a7516843', '8049817a-9d6a-4979-9b3a-e3f3ae7d9b19', 'subtopic'::public.curated_course_node_type, 'Hypergeometric', 'Hypergeometric identifies a specific object, distinction, or relationship within discrete models. Learners need to recognize and use it before combining this module''s ideas in later work. After geometric, hypergeometric supplies what is needed to address poisson.', 2),
  ('6411ef66-9f95-491e-a84c-fe129f9131e6', '4e6074d2-8d41-4d91-afdd-1605a7516843', '8049817a-9d6a-4979-9b3a-e3f3ae7d9b19', 'subtopic'::public.curated_course_node_type, 'Poisson', 'Poisson identifies a specific object, distinction, or relationship within discrete models. Learners need to recognize and use it before combining this module''s ideas in later work. After hypergeometric, poisson supplies what is needed to address engineering examples.', 3),
  ('841aa955-06b0-4bc2-857b-2cc2110fe493', '4e6074d2-8d41-4d91-afdd-1605a7516843', '8049817a-9d6a-4979-9b3a-e3f3ae7d9b19', 'subtopic'::public.curated_course_node_type, 'Engineering examples', 'Engineering examples identifies a specific object, distinction, or relationship within discrete models. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, engineering examples carries the completed idea into continuous models.', 4),
  ('de6d1bae-acae-4dea-aaad-a9579aedf2cf', '4e6074d2-8d41-4d91-afdd-1605a7516843', null, 'topic'::public.curated_course_node_type, 'Continuous models', 'This module builds directly on discrete models and develops continuous models. It belongs here because its methods and distinctions are prerequisites for joint behavior.', 3),
  ('9c42641c-f83e-4dd8-b551-c9c036c8e0d7', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'de6d1bae-acae-4dea-aaad-a9579aedf2cf', 'subtopic'::public.curated_course_node_type, 'Normal', 'Normal identifies a specific object, distinction, or relationship within continuous models. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before exponential because that next topic assumes this starting point.', 0),
  ('f8426e30-c2ad-4f42-9b87-7abeb18c611c', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'de6d1bae-acae-4dea-aaad-a9579aedf2cf', 'subtopic'::public.curated_course_node_type, 'Exponential', 'Exponential identifies a specific object, distinction, or relationship within continuous models. Learners need to recognize and use it before combining this module''s ideas in later work. After normal, exponential supplies what is needed to address weibull.', 1),
  ('c642074f-5b9c-48b4-90e3-5243d418b72e', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'de6d1bae-acae-4dea-aaad-a9579aedf2cf', 'subtopic'::public.curated_course_node_type, 'Weibull', 'Weibull identifies a specific object, distinction, or relationship within continuous models. Learners need to recognize and use it before combining this module''s ideas in later work. After exponential, weibull supplies what is needed to address lognormal.', 2),
  ('fd04529f-cd44-43de-a64e-f7673f2d9699', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'de6d1bae-acae-4dea-aaad-a9579aedf2cf', 'subtopic'::public.curated_course_node_type, 'Lognormal', 'Lognormal identifies a specific object, distinction, or relationship within continuous models. Learners need to recognize and use it before combining this module''s ideas in later work. After weibull, lognormal supplies what is needed to address transformations.', 3),
  ('a4fec908-9f62-4ce5-8f31-c3679ed3b097', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'de6d1bae-acae-4dea-aaad-a9579aedf2cf', 'subtopic'::public.curated_course_node_type, 'Transformations', 'Transformations makes difficult behavior in continuous models tractable while exposing the assumptions and accuracy limits used by later methods. As the final topic in this module, transformations carries the completed idea into joint behavior.', 4),
  ('03285367-5d4c-453f-907b-8422a232bc58', '4e6074d2-8d41-4d91-afdd-1605a7516843', null, 'topic'::public.curated_course_node_type, 'Joint behavior', 'This module builds directly on continuous models and develops joint behavior. It belongs here because its methods and distinctions are prerequisites for sampling distributions.', 4),
  ('7ded0d99-6a38-48db-a3c0-b8a13eda7fa7', '4e6074d2-8d41-4d91-afdd-1605a7516843', '03285367-5d4c-453f-907b-8422a232bc58', 'subtopic'::public.curated_course_node_type, 'Covariance', 'Covariance identifies a specific object, distinction, or relationship within joint behavior. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before correlation because that next topic assumes this starting point.', 0),
  ('731c2aba-cd8c-4049-b1ff-76df2cba335a', '4e6074d2-8d41-4d91-afdd-1605a7516843', '03285367-5d4c-453f-907b-8422a232bc58', 'subtopic'::public.curated_course_node_type, 'Correlation', 'Correlation identifies a specific object, distinction, or relationship within joint behavior. Learners need to recognize and use it before combining this module''s ideas in later work. After covariance, correlation supplies what is needed to address conditional distributions.', 1),
  ('dcf4ed53-5f3b-4426-ad0d-b0c005a795f8', '4e6074d2-8d41-4d91-afdd-1605a7516843', '03285367-5d4c-453f-907b-8422a232bc58', 'subtopic'::public.curated_course_node_type, 'Conditional distributions', 'Conditional distributions gives joint behavior a reusable representation for organizing assumptions, variables, and relationships before analysis begins. After correlation, conditional distributions supplies what is needed to address functions of variables.', 2),
  ('2559b50c-f662-4a6e-abda-10c87966f077', '4e6074d2-8d41-4d91-afdd-1605a7516843', '03285367-5d4c-453f-907b-8422a232bc58', 'subtopic'::public.curated_course_node_type, 'Functions of variables', 'Functions of variables identifies a specific object, distinction, or relationship within joint behavior. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, functions of variables carries the completed idea into sampling distributions.', 3),
  ('87522a0d-7dd3-4593-9f8b-d363a4bef316', '4e6074d2-8d41-4d91-afdd-1605a7516843', null, 'topic'::public.curated_course_node_type, 'Sampling distributions', 'This module builds directly on joint behavior and develops sampling distributions. It belongs here because its methods and distinctions are prerequisites for confidence intervals.', 5),
  ('0c12581b-6cbc-493e-97ff-96350bc01942', '4e6074d2-8d41-4d91-afdd-1605a7516843', '87522a0d-7dd3-4593-9f8b-d363a4bef316', 'subtopic'::public.curated_course_node_type, 'Estimators', 'Estimators identifies a specific object, distinction, or relationship within sampling distributions. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before bias/variance because that next topic assumes this starting point.', 0),
  ('37c2a3b7-e5fc-4173-9457-c7041c964990', '4e6074d2-8d41-4d91-afdd-1605a7516843', '87522a0d-7dd3-4593-9f8b-d363a4bef316', 'subtopic'::public.curated_course_node_type, 'Bias/variance', 'Bias/variance identifies a specific object, distinction, or relationship within sampling distributions. Learners need to recognize and use it before combining this module''s ideas in later work. After estimators, bias/variance supplies what is needed to address clt.', 1),
  ('5af4d6eb-23d1-4a93-8071-83dceb0ef7ba', '4e6074d2-8d41-4d91-afdd-1605a7516843', '87522a0d-7dd3-4593-9f8b-d363a4bef316', 'subtopic'::public.curated_course_node_type, 'CLT', 'CLT identifies a specific object, distinction, or relationship within sampling distributions. Learners need to recognize and use it before combining this module''s ideas in later work. After bias/variance, clt supplies what is needed to address standard errors.', 2),
  ('17491f9d-af64-4d7f-ac85-6573c4ddb532', '4e6074d2-8d41-4d91-afdd-1605a7516843', '87522a0d-7dd3-4593-9f8b-d363a4bef316', 'subtopic'::public.curated_course_node_type, 'Standard errors', 'Standard errors makes the validity limits of sampling distributions explicit, showing when an otherwise correct method or system can become unreliable. As the final topic in this module, standard errors carries the completed idea into confidence intervals.', 3),
  ('e8f45668-ed0c-4919-afe0-a5c45979eed9', '4e6074d2-8d41-4d91-afdd-1605a7516843', null, 'topic'::public.curated_course_node_type, 'Confidence intervals', 'This module builds directly on sampling distributions and develops confidence intervals. It belongs here because its methods and distinctions are prerequisites for hypothesis testing.', 6),
  ('b03bdee9-1011-4711-9357-4fbd4fac56d4', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'e8f45668-ed0c-4919-afe0-a5c45979eed9', 'subtopic'::public.curated_course_node_type, 'Means', 'Means identifies a specific object, distinction, or relationship within confidence intervals. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before proportions because that next topic assumes this starting point.', 0),
  ('cd992683-5178-4f7b-824c-37bdefbb67d6', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'e8f45668-ed0c-4919-afe0-a5c45979eed9', 'subtopic'::public.curated_course_node_type, 'Proportions', 'Proportions identifies a specific object, distinction, or relationship within confidence intervals. Learners need to recognize and use it before combining this module''s ideas in later work. After means, proportions supplies what is needed to address variances.', 1),
  ('b00b52aa-75c2-44d9-a7a6-312fac8968f3', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'e8f45668-ed0c-4919-afe0-a5c45979eed9', 'subtopic'::public.curated_course_node_type, 'Variances', 'Variances identifies a specific object, distinction, or relationship within confidence intervals. Learners need to recognize and use it before combining this module''s ideas in later work. After proportions, variances supplies what is needed to address sample-size planning.', 2),
  ('14f9c172-be1d-4fe9-b63d-b2f6c2c25650', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'e8f45668-ed0c-4919-afe0-a5c45979eed9', 'subtopic'::public.curated_course_node_type, 'Sample-size planning', 'Sample-size planning turns the theory of confidence intervals into a defensible decision and exposes the relevant structure, cost, or performance trade-offs. As the final topic in this module, sample-size planning carries the completed idea into hypothesis testing.', 3),
  ('766b07fe-c8c0-44e0-8df2-3c1c7e6a09be', '4e6074d2-8d41-4d91-afdd-1605a7516843', null, 'topic'::public.curated_course_node_type, 'Hypothesis testing', 'This module builds directly on confidence intervals and develops hypothesis testing. It belongs here because its methods and distinctions are prerequisites for regression.', 7);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('2bf3264e-4600-4d67-93e1-a3e3723caed8', '4e6074d2-8d41-4d91-afdd-1605a7516843', '766b07fe-c8c0-44e0-8df2-3c1c7e6a09be', 'subtopic'::public.curated_course_node_type, 'Errors', 'Errors makes the validity limits of hypothesis testing explicit, showing when an otherwise correct method or system can become unreliable. It appears before p-values because that next topic assumes this starting point.', 0),
  ('9d2755f1-78e6-429c-86f3-99acf0941520', '4e6074d2-8d41-4d91-afdd-1605a7516843', '766b07fe-c8c0-44e0-8df2-3c1c7e6a09be', 'subtopic'::public.curated_course_node_type, 'P-values', 'P-values identifies a specific object, distinction, or relationship within hypothesis testing. Learners need to recognize and use it before combining this module''s ideas in later work. After errors, p-values supplies what is needed to address power.', 1),
  ('999e6d36-870c-4e44-8b93-cf86288ec204', '4e6074d2-8d41-4d91-afdd-1605a7516843', '766b07fe-c8c0-44e0-8df2-3c1c7e6a09be', 'subtopic'::public.curated_course_node_type, 'Power', 'Power identifies a specific object, distinction, or relationship within hypothesis testing. Learners need to recognize and use it before combining this module''s ideas in later work. After p-values, power supplies what is needed to address one- and two-sample procedures.', 2),
  ('aecf9c63-2a7a-4489-98b6-cae59f8480a7', '4e6074d2-8d41-4d91-afdd-1605a7516843', '766b07fe-c8c0-44e0-8df2-3c1c7e6a09be', 'subtopic'::public.curated_course_node_type, 'One- and two-sample procedures', 'One- and two-sample procedures identifies a specific object, distinction, or relationship within hypothesis testing. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, one- and two-sample procedures carries the completed idea into regression.', 3),
  ('61a31a25-fdb4-42f9-9cd6-3e6b801219fd', '4e6074d2-8d41-4d91-afdd-1605a7516843', null, 'topic'::public.curated_course_node_type, 'Regression', 'This module builds directly on hypothesis testing and develops regression. It belongs here because its methods and distinctions are prerequisites for multiple regression and anova.', 8),
  ('efd53cc1-de5e-4623-9b4e-fe290579d4e0', '4e6074d2-8d41-4d91-afdd-1605a7516843', '61a31a25-fdb4-42f9-9cd6-3e6b801219fd', 'subtopic'::public.curated_course_node_type, 'Least squares', 'Least squares identifies a specific object, distinction, or relationship within regression. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before interpretation because that next topic assumes this starting point.', 0),
  ('c6fd1e70-6aa9-4493-b0b9-a148db997ebb', '4e6074d2-8d41-4d91-afdd-1605a7516843', '61a31a25-fdb4-42f9-9cd6-3e6b801219fd', 'subtopic'::public.curated_course_node_type, 'Interpretation', 'Interpretation identifies a specific object, distinction, or relationship within regression. Learners need to recognize and use it before combining this module''s ideas in later work. After least squares, interpretation supplies what is needed to address residuals.', 1),
  ('205bb9aa-ff94-40c8-a07b-390037214a34', '4e6074d2-8d41-4d91-afdd-1605a7516843', '61a31a25-fdb4-42f9-9cd6-3e6b801219fd', 'subtopic'::public.curated_course_node_type, 'Residuals', 'Residuals identifies a specific object, distinction, or relationship within regression. Learners need to recognize and use it before combining this module''s ideas in later work. After interpretation, residuals supplies what is needed to address intervals.', 2),
  ('bd3427fa-6a0d-4145-954a-9d3f948591f1', '4e6074d2-8d41-4d91-afdd-1605a7516843', '61a31a25-fdb4-42f9-9cd6-3e6b801219fd', 'subtopic'::public.curated_course_node_type, 'Intervals', 'Intervals identifies a specific object, distinction, or relationship within regression. Learners need to recognize and use it before combining this module''s ideas in later work. After residuals, intervals supplies what is needed to address transformations.', 3),
  ('66bd75da-fc05-408c-9c27-44eaffd1a38d', '4e6074d2-8d41-4d91-afdd-1605a7516843', '61a31a25-fdb4-42f9-9cd6-3e6b801219fd', 'subtopic'::public.curated_course_node_type, 'Transformations', 'Transformations makes difficult behavior in regression tractable while exposing the assumptions and accuracy limits used by later methods. As the final topic in this module, transformations carries the completed idea into multiple regression and anova.', 4),
  ('ab9d21cb-739d-4fc2-8027-5ac02f13d0b3', '4e6074d2-8d41-4d91-afdd-1605a7516843', null, 'topic'::public.curated_course_node_type, 'Multiple regression and ANOVA', 'This module builds directly on regression and develops multiple regression and anova. It belongs here because its methods and distinctions are prerequisites for experimental design.', 9),
  ('7a6197f0-0930-43b6-b6df-fa100c6706a8', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'ab9d21cb-739d-4fc2-8027-5ac02f13d0b3', 'subtopic'::public.curated_course_node_type, 'Factors', 'Factors identifies a specific object, distinction, or relationship within multiple regression and anova. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before interactions because that next topic assumes this starting point.', 0),
  ('ff5e5505-b1f3-43c8-96fa-f1f9385190bb', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'ab9d21cb-739d-4fc2-8027-5ac02f13d0b3', 'subtopic'::public.curated_course_node_type, 'Interactions', 'Interactions identifies a specific object, distinction, or relationship within multiple regression and anova. Learners need to recognize and use it before combining this module''s ideas in later work. After factors, interactions supplies what is needed to address model comparison.', 1),
  ('b98beb67-bd79-4068-984c-7a7718feedce', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'ab9d21cb-739d-4fc2-8027-5ac02f13d0b3', 'subtopic'::public.curated_course_node_type, 'Model comparison', 'Model comparison gives multiple regression and anova a reusable representation for organizing assumptions, variables, and relationships before analysis begins. After interactions, model comparison supplies what is needed to address diagnostics.', 2),
  ('c6927516-182d-413a-8204-ed92158ec666', '4e6074d2-8d41-4d91-afdd-1605a7516843', 'ab9d21cb-739d-4fc2-8027-5ac02f13d0b3', 'subtopic'::public.curated_course_node_type, 'Diagnostics', 'Diagnostics makes the validity limits of multiple regression and anova explicit, showing when an otherwise correct method or system can become unreliable. As the final topic in this module, diagnostics carries the completed idea into experimental design.', 3),
  ('71fbcec5-d273-4a5c-b275-408f2a01aa10', '4e6074d2-8d41-4d91-afdd-1605a7516843', null, 'topic'::public.curated_course_node_type, 'Experimental design', 'This module builds directly on multiple regression and anova and develops experimental design. It belongs here because its methods and distinctions are prerequisites for reliability and statistical quality.', 10),
  ('1712899b-f78c-4d5d-ba55-acee594f0617', '4e6074d2-8d41-4d91-afdd-1605a7516843', '71fbcec5-d273-4a5c-b275-408f2a01aa10', 'subtopic'::public.curated_course_node_type, 'Randomization', 'Randomization identifies a specific object, distinction, or relationship within experimental design. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before blocking because that next topic assumes this starting point.', 0),
  ('abec8394-ab51-44bd-bad0-b2c81f5e93a3', '4e6074d2-8d41-4d91-afdd-1605a7516843', '71fbcec5-d273-4a5c-b275-408f2a01aa10', 'subtopic'::public.curated_course_node_type, 'Blocking', 'Blocking identifies a specific object, distinction, or relationship within experimental design. Learners need to recognize and use it before combining this module''s ideas in later work. After randomization, blocking supplies what is needed to address factorial designs.', 1),
  ('4e2315f6-fd61-4f1a-9927-e92b433943c0', '4e6074d2-8d41-4d91-afdd-1605a7516843', '71fbcec5-d273-4a5c-b275-408f2a01aa10', 'subtopic'::public.curated_course_node_type, 'Factorial designs', 'Factorial designs turns the theory of experimental design into a defensible decision and exposes the relevant structure, cost, or performance trade-offs. After blocking, factorial designs supplies what is needed to address confounding.', 2),
  ('138a16ec-e4b2-41aa-9585-870cb98a485d', '4e6074d2-8d41-4d91-afdd-1605a7516843', '71fbcec5-d273-4a5c-b275-408f2a01aa10', 'subtopic'::public.curated_course_node_type, 'Confounding', 'Confounding identifies a specific object, distinction, or relationship within experimental design. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, confounding carries the completed idea into reliability and statistical quality.', 3),
  ('4a038d40-7251-42b8-90a8-7b7c66c4f117', '4e6074d2-8d41-4d91-afdd-1605a7516843', null, 'topic'::public.curated_course_node_type, 'Reliability and statistical quality', 'This culminating module draws on experimental design and develops reliability and statistical quality. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.', 11),
  ('51084064-afc4-4193-b99d-f78570a1c64d', '4e6074d2-8d41-4d91-afdd-1605a7516843', '4a038d40-7251-42b8-90a8-7b7c66c4f117', 'subtopic'::public.curated_course_node_type, 'Life data', 'Life data connects reliability and statistical quality to observable evidence and defines what a valid measurement or interpretation must support. It appears before control charts because that next topic assumes this starting point.', 0),
  ('52a8da27-d87b-4432-822b-30e4f4ce9f3e', '4e6074d2-8d41-4d91-afdd-1605a7516843', '4a038d40-7251-42b8-90a8-7b7c66c4f117', 'subtopic'::public.curated_course_node_type, 'Control charts', 'Control charts explains how reliability and statistical quality behaves under misuse, faults, or constraints, which is essential for responsible real-world application. After life data, control charts supplies what is needed to address capability.', 1),
  ('9ab634fa-7174-456f-92a2-d6035cd966a0', '4e6074d2-8d41-4d91-afdd-1605a7516843', '4a038d40-7251-42b8-90a8-7b7c66c4f117', 'subtopic'::public.curated_course_node_type, 'Capability', 'Capability identifies a specific object, distinction, or relationship within reliability and statistical quality. Learners need to recognize and use it before combining this module''s ideas in later work. After control charts, capability supplies what is needed to address reproducibility.', 2),
  ('003a7575-b72b-481a-8e20-c23a1fd9d2a8', '4e6074d2-8d41-4d91-afdd-1605a7516843', '4a038d40-7251-42b8-90a8-7b7c66c4f117', 'subtopic'::public.curated_course_node_type, 'Reproducibility', 'Reproducibility identifies a specific object, distinction, or relationship within reliability and statistical quality. Learners need to recognize and use it before combining this module''s ideas in later work. As the final course topic, reproducibility requires ideas from the complete path to be integrated and transferred.', 3);
